-- dynasties
INSERT INTO dynasties (id, name, alt_names, ethnicity, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('guo-chunqiu', '西虢国', ARRAY['虢','虢国','南虢'], NULL, 'cn', 'east_asia', -1046, 1, NULL, 'year', -655, 12, NULL, 'month', -12540, -7837, 'ochre', NULL, NULL, '周朝姬姓诸侯国，本条目聚焦西虢；其东迁后三门峡一带亦称南虢。西虢传统君主序列：虢叔 → 郭叔 → 史料缺 → 城公 → 史料缺 → 厉公 → 宣公 → 文公 → 石父 → 翰 → 忌父 → 林父 → 丑。长父之后的君主，一说为宣公，一说为文公。
有待考证的西虢君主世系：易父 → 宄公 → 幽叔 → 德叔 → 师丞。五代家族世系见师丞钟，但其是否兼任西虢君主及与主序列的衔接存在争议。
东、西虢始封君归属存在异说。西虢东迁后三门峡一带称南虢，前655年晋献公借道虞国灭虢。《左传·僖公五年》记虢公丑亡国后出奔京师。')
