INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-r1', '叔', 'guo-chunqiu', ARRAY[]::text[], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢叔，姬姓，周文王弟，曾任文王卿士。传统说法以其为西虢始封君；东、西虢封君归属存在异说，具体在位起讫不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢叔"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"}]'::jsonb, NULL, NULL, '叔')
