INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-r2', '郭叔', 'guo-chunqiu', ARRAY['虢叔'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '郭叔（一作虢叔），西周虢国人物。《逸周书·王会》记其掌天子贡币；《虢国研究》认为其为始封君虢叔之子。具体在位起讫不详，与虢城公之间世系失考，不能确定为虢城公的直接前任。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郭叔"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"《逸周书·王会》（郭叔掌贡币）","url":"https://ctext.org/lost-book-of-zhou/wang-hui/zh"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"}]'::jsonb, NULL, NULL, '郭叔')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, dynasty_id = EXCLUDED.dynasty_id, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-r3', '城公', 'guo-chunqiu', ARRAY['虢成公'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢城公，班簋铭文所见西周虢国人物。铭文记周王命毛伯接替其职务，并非国君传位记载。其所属东、西虢及活动年代存在异说，一说为周昭王、穆王时期人；具体在位起讫及直接前任失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢城公"},{"label":"周朝诸侯国君主列表（西虢中间世系失考）","url":"https://zh.wikipedia.org/wiki/周朝諸侯國君主列表#西虢国"},{"label":"西虢国（金文人物、年代及世系争议）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"},{"label":"《班簋铭文》（毛伯接替虢城公职务）","url":"https://zh.wikisource.org/wiki/班簋銘文"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"周朝（共时定位采用的年表）","url":"https://zh.wikipedia.org/wiki/周朝"},{"label":"冯时《班簋铭文补释》（穆王时期）","url":"https://www.ctwx.tsinghua.edu.cn/__local/A/61/04/3B0E595B6786E89BFDFF5B51A67_192072D8_490B29.pdf?e=.pdf"}]'::jsonb, NULL, NULL, '城公')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, dynasty_id = EXCLUDED.dynasty_id, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
