VALUES ('guo-r4', '长父', 'guo-chunqiu', ARRAY['虢厉公','虢仲','虢公长父'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢公长父，又称虢厉公、虢仲，主要活动于周厉王时期，曾任卿士并奉命征讨淮夷。具体在位年代不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公长父"},{"label":"河南博物院《虢硕父簠》","url":"https://www.chnmus.net/ch/collection/appraise/details.html?id=512153734134559839"}]'::jsonb, '厉公', NULL, '虢公长父')
