VALUES ('guo-r5', '子白', 'guo-chunqiu', ARRAY['虢季子白','虢季'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢宣公，亦称虢季子白，周宣王时期率军攻猃狁，相关事迹见虢季子白盘铭文。虢公长父之后的继承顺序有宣公、文公两说。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢宣公"},{"label":"虢国君主世系（宣公、文公顺序异说）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"}]'::jsonb, '宣公', NULL, '虢宣公')
