VALUES ('guo-r6', '季', 'guo-chunqiu', ARRAY['虢季'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢文公，周宣王时期任卿士，曾谏宣王举行籍田礼，事见《国语·周语上》。具体在位年代不详；虢公长父之后的继承顺序有宣公、文公两说。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢文公"},{"label":"虢国君主世系（宣公、文公顺序异说）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"}]'::jsonb, '文公', NULL, '虢文公')
