VALUES ('guo-r9', '忌父', 'guo-chunqiu', ARRAY[]::text[], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢公忌父，周平王晚年受用为王室卿士，前720年周平王有意分郑伯政于忌父，前715年任右卿士，见《左传·隐公八年》及相关年表。即位年不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公忌父"}]'::jsonb, NULL, NULL, '虢公忌父')
