VALUES ('guo-r10', '林父', 'guo-chunqiu', ARRAY['虢仲'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢公林父，姬姓虢氏，曾任周王室卿士。前707年繻葛之战率王室右军，前706、前703年奉命讨伐曲沃，前702年被迫出奔虞国，均见《左传》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公林父"}]'::jsonb, NULL, NULL, '虢公林父')
