INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-gong-chou', '丑', 'guo-chunqiu', ARRAY['虢公醜','虢叔'], '姬', '虢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '虢公丑（又作虢公醜），春秋时期西虢末代君主，生卒及父祖世系不详。前673年与郑厉公合兵平定王子颓之乱，助周惠王复位。前655年晋献公再次借道虞国灭虢，虢公丑出奔周王室京师；《左传》同段记被俘者为虞公及井伯。虢公丑此后的确切卒年不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢公丑"},{"label":"《左传·僖公五年》（晋灭虢、虢公丑奔京师）","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"}]'::jsonb, NULL, NULL, '虢公丑')
