INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-ji-yifu', '挞', 'guo-chunqiu', ARRAY['虢季易父','易父'], '姬', '虢季', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['贵族','西虢君主身份待考'], '虢季易父，姬姓，名挞，字易父，西周虢季家族人物，虢宄公之父。师丞钟记其家族五代世系；其是否兼任西虢君主存在争议，在位起讫不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢季易父"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]'::jsonb, NULL, NULL, '虢季易父')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, dynasty_id = EXCLUDED.dynasty_id, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-gui-gong', '虢宄公', 'guo-chunqiu', ARRAY['虢宫公','师哉','宄公'], '姬', '虢季', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['贵族','西虢君主身份待考'], '虢宄公，一作虢宫公，姬姓，字哉，虢季易父之子、虢幽叔之父。师哉鼎记其任周王室军职及受命为太师；主要活动于周穆王、共王时期。其西虢君主身份有争议，在位起讫不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢宄公"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]'::jsonb, '宄公,宫公', NULL, '虢宄公')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, dynasty_id = EXCLUDED.dynasty_id, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, dynasty_id, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('guo-you-shu', '虢幽叔', 'guo-chunqiu', ARRAY['师望','幽叔'], '姬', '虢季', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['贵族','西虢君主身份待考'], '虢幽叔，姬姓，字望，虢宄公之子、虢德叔之父。师望鼎记其承袭父亲的太师职务并受周王赏赐；活动年代有共王时期、懿王至孝王时期等说。其西虢君主身份有争议，在位起讫不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢幽叔"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]'::jsonb, '幽叔', NULL, '虢幽叔')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, dynasty_id = EXCLUDED.dynasty_id, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
