VALUES ('guo-shi-cheng', '师丞', 'guo-chunqiu', ARRAY['虢公师丞'], '姬', '虢季', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['贵族','西虢君主身份待考'], '师丞，姬姓，字丞，虢德叔之子。师丞钟列叙虢季易父、宄公、幽叔、德叔至师丞五代世系。其活动年代及西虢君主身份存在争议，与城公、厉公主序列的衔接未能确定，在位起讫不详。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/师丞"},{"label":"虢国君主世系（主序列与待考虢季家族）","url":"https://zh.wikipedia.org/wiki/Template:虢國君主"},{"label":"西虢国（金文家族君主身份待考）","url":"https://zh.wikipedia.org/wiki/西虢国#金文中的虢国氏族"}]'::jsonb, NULL, NULL, '师丞')
