ON CONFLICT (id) DO UPDATE SET dynasty_id = EXCLUDED.dynasty_id, person_id = EXCLUDED.person_id, title = EXCLUDED.title, era_names = EXCLUDED.era_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, start_confidence = EXCLUDED.start_confidence, end_confidence = EXCLUDED.end_confidence, claim_track = EXCLUDED.claim_track, claim_label = EXCLUDED.claim_label, is_main = EXCLUDED.is_main;

-- location_mapping
INSERT INTO location_mapping (id, location_id, kind, external_id, historical_name, spatial_precision, start_year, start_month, start_day, end_year, end_month, end_day, start_abs, end_abs, start_confidence, end_confidence, role, note, links) VALUES ('capital-guo-shangyang', 'loc-102fb3aa5ae9b60b645596098d59db9f', 'dynasty', 'guo-chunqiu', '上阳', NULL, -770, 1, NULL, -655, 12, NULL, -9228, -7837, 'year', 'month', 'primary', '虢都上阳。始年按虢国东迁后在三门峡建都的约数记；遗址位于今三门峡李家窑一带。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/虢国"}]'::jsonb) ON CONFLICT(id) DO UPDATE SET location_id=EXCLUDED.location_id, kind=EXCLUDED.kind, external_id=EXCLUDED.external_id, historical_name=EXCLUDED.historical_name, spatial_precision=EXCLUDED.spatial_precision, start_year=EXCLUDED.start_year, start_month=EXCLUDED.start_month, start_day=EXCLUDED.start_day, end_year=EXCLUDED.end_year, end_month=EXCLUDED.end_month, end_day=EXCLUDED.end_day, start_abs=EXCLUDED.start_abs, end_abs=EXCLUDED.end_abs, start_confidence=EXCLUDED.start_confidence, end_confidence=EXCLUDED.end_confidence, role=EXCLUDED.role, note=EXCLUDED.note, links=EXCLUDED.links;

-- Remove stale reigns from managed dynasties (superseded ids from older imports)
WITH stale AS (
  DELETE FROM reigns
  WHERE dynasty_id IN ('guo-chunqiu') AND id NOT IN ('reign-guo-r1-guo-chunqiu', 'reign-guo-r2-guo-chunqiu', 'reign-missing-guo-chunqiu--1020', 'reign-guo-r3-guo-chunqiu', 'reign-missing-guo-chunqiu--922', 'reign-guo-r4-guo-chunqiu', 'reign-guo-r5-guo-chunqiu', 'reign-guo-r6-guo-chunqiu', 'reign-guo-r7-guo-chunqiu', 'reign-guo-r8-guo-chunqiu', 'reign-guo-r9-guo-chunqiu', 'reign-guo-r10-guo-chunqiu', 'reign-guo-gong-chou-guo-chunqiu')
  RETURNING person_id
)
DELETE FROM persons p
WHERE p.id IN (SELECT DISTINCT person_id FROM stale)
  AND NOT EXISTS (SELECT 1 FROM reigns r WHERE r.person_id = p.id)
  AND NOT EXISTS (SELECT 1 FROM entity_associations a WHERE (a.a_type = 'person' AND a.a_id = p.id) OR (a.b_type = 'person' AND a.b_id = p.id))
  AND NOT EXISTS (
    SELECT 1 FROM relations rel
    WHERE (rel.from_type = 'person' AND rel.from_id = p.id)
       OR (rel.to_type = 'person' AND rel.to_id = p.id)
  );
SELECT rebuild_person_search_terms();

COMMIT;
